/* Base de conhecimento do Coach. k = palavras-chave, frase = trechos que reforçam o tema, r = resposta. */
window.CONHECIMENTO=[
 {q:'Jejum intermitente funciona?',k:['jejum intermitente','jejum','janela de alimentacao','16 8'],r:'Jejum intermitente é só uma forma de organizar as calorias. Funciona para quem se adapta bem, porque facilita comer menos, mas não queima mais gordura que uma dieta normal com as mesmas calorias. Para ganhar massa, costuma atrapalhar a bater a proteína.'},
 {q:'Posso comer doce?',k:['doce','acucar','chocolate','sobremesa','besteira','lixo','fast food','refrigerante'],r:'Pode, com moderação. Se 80 a 90% da sua alimentação for de comida de verdade e a meta de calorias e proteína estiver em dia, um doce de vez em quando não atrapalha. Refrigerante comum soma muitas calorias sem matar a fome: prefira a versão zero.'},
 {q:'O que é bulking e cutting?',k:['bulking','cutting','bulk','cut','fase de ganho','fase de perda'],r:'Bulking é a fase de comer acima do gasto para ganhar massa, idealmente devagar, uns 0,25 a 0,5 kg por semana. Cutting é a fase de déficit para perder gordura mantendo o músculo, com proteína alta e treino pesado. Quem está começando costuma conseguir os dois ao mesmo tempo.'},
 {q:'Quantas refeições por dia?',k:['quantas refeicoes','refeicoes por dia','comer de 3 em 3 horas','frequencia alimentar'],r:'O número de refeições importa pouco. O que conta é o total de calorias e de proteína no dia. Entre 3 e 5 refeições facilita distribuir a proteína, com uns 25 a 40 g em cada.'},
 {q:'Arroz e feijão é bom para quem treina?',k:['arroz e feijao','arroz feijao','prato brasileiro','comida caseira'],r:'É ótimo. Arroz e feijão juntos formam uma proteína completa, têm carboidrato para o treino, fibras e ferro. Com uma carne, ovos ou outra proteína e uma salada, é um prato de atleta.'},
 {q:'Como ganhar massa muscular?',k:['ganhar massa','hipertrofia','crescer','musculo','volume','ficar grande','ficar forte'],frase:['ganhar massa','ganhar musculo','hipertrofia'],r:'Três coisas juntas: treino com progressão de carga, comida em leve superávit com proteína suficiente e sono. Faça as séries perto do limite, suba o peso quando bater todas as repetições e coma um pouco acima do que gasta. O resto é detalhe.'},
 {q:'Como perder gordura sem perder músculo?',k:['perder gordura','emagrecer','secar','barriga','perder peso','gordura localizada','queimar gordura'],frase:['perder gordura','perder barriga','emagrecer'],r:'Déficit calórico moderado, de 15 a 20%, proteína alta e musculação pesada para avisar o corpo que o músculo ainda é necessário. Não existe queimar gordura só de um lugar: abdominal fortalece o abdômen, mas quem tira a gordura de cima é o déficit. Caminhadas ajudam muito.'},
 {q:'O que é definição?',k:['definir','definicao','definido','trincado','recomposicao','shape'],r:'Definição é ter músculo e pouca gordura por cima. Para quem está começando ou voltando, dá para ganhar músculo e perder gordura ao mesmo tempo (recomposição) comendo perto da manutenção com bastante proteína. Para quem já treina há anos, normalmente alterna fases de ganho e de perda.'},
 {q:'Quantas séries por músculo na semana?',k:['quantas series','series semana','volume semanal','volume treino','quantos exercicios'],frase:['quantas series'],r:'Para crescer, algo entre 10 e 20 séries por músculo na semana, contando as séries que chegam perto do limite. Iniciante cresce bem com 8 a 12. Mais que 20 raramente compensa. O Coach mostra seu volume semanal por grupo.'},
 {q:'Quantas vezes treinar cada músculo?',k:['frequencia','vezes semana','quantos dias','treinar todo dia','mesmo musculo','dias seguidos'],r:'Duas vezes por semana por músculo costuma render mais que uma. Músculos grandes precisam de umas 48 horas para recuperar, então evite pegar pesado no mesmo grupo em dias seguidos. Braço, panturrilha e abdômen recuperam mais rápido.'},
 {q:'Quanto tempo descansar entre as séries?',k:['descanso','descansar','intervalo','tempo entre series','pausa'],frase:['entre series','entre as series'],r:'Exercícios grandes, como supino, agachamento e remada, rendem mais com 90 s a 2 min. Isolados, como rosca e elevação lateral, de 45 a 75 s. Para força, até 3 min. Descanso curto demais derruba as repetições da série seguinte e atrapalha o ganho.'},
 {q:'Por que 3 séries de 10?',k:['3 series','10 repeticoes','repeticoes','reps','quantas repeticoes','faixa repeticao'],r:'Três séries de 10 é um ponto de partida que funciona para quase todo mundo e facilita acompanhar a evolução. Hipertrofia acontece entre 6 e 30 repetições se a série chegar perto do limite. Você pode mudar séries e repetições de cada exercício em Plano.'},
 {q:'Como saber a carga certa?',k:['carga','peso certo','quanto peso','carga ideal','escolher peso'],r:'Escolha um peso em que a 10ª repetição saia difícil, mas com técnica limpa, sobrando 1 ou 2 no tanque. Se fizer 15 fácil, está leve. Se não chegar a 8, está pesado. Quando bater 10 em todas as séries, suba um pouco.'},
 {q:'O que é progressão de carga?',k:['progressao','subir peso','aumentar carga','evoluir','estagnado','parei de evoluir','plato'],r:'É fazer um pouco mais ao longo do tempo: mais peso, mais repetições ou melhor execução. Aqui usamos a progressão dupla: bateu as 10 repetições em todas as séries, sobe o peso. Se travar por 3 treinos, troque a variação do exercício ou durma e coma melhor.'},
 {q:'Preciso ir até a falha?',k:['falha','falha muscular','ate falhar','limite'],r:'Não em toda série. Chegar a 1 ou 2 repetições da falha já dá quase todo o estímulo. Falha total cansa muito, principalmente em exercícios pesados como agachamento e terra. Deixe a falha para a última série dos isolados.'},
 {q:'O que é drop-set, bi-set e rest-pause?',k:['drop set','dropset','bi set','biset','rest pause','tecnica avancada','super serie'],r:'Drop-set: no fim da série, tira uns 30% do peso e continua. Bi-set: dois exercícios seguidos sem descanso. Rest-pause: chega perto da falha, descansa 15 s e faz mais algumas. São atalhos para economizar tempo ou dar um choque, úteis depois que a base está boa.'},
 {q:'Como aquecer?',k:['aquecimento','aquecer','antes do treino'],r:'5 minutos de algo leve para subir a temperatura, mobilidade da articulação que vai trabalhar e 1 ou 2 séries leves do primeiro exercício. Alongamento estático longo antes do treino pesado não ajuda e pode tirar um pouco de força.'},
 {q:'Alongar ajuda?',k:['alongamento','alongar','flexibilidade','mobilidade'],r:'Alongar melhora flexibilidade, mas não previne dor muscular. Faça depois do treino ou em outro horário se quiser ganhar mobilidade. Exercícios com amplitude completa já alongam o músculo sob carga.'},
 {q:'Dor muscular depois do treino é normal?',k:['dor muscular','dor tardia','dolorido','doms','corpo doendo','dor depois'],r:'Sim, a dor de 24 a 72 h depois é normal, principalmente no começo ou com exercício novo. Ela não mede a qualidade do treino. Movimento leve, sono e comida ajudam. Dor aguda, em pontada ou na articulação é outra coisa: pare o exercício.'},
 {q:'Senti dor na articulação, e agora?',k:['dor no ombro','dor no joelho','dor lombar','dor nas costas','lesao','machuquei','dor articulacao','dor no punho','dor no cotovelo'],r:'Dor em pontada, na articulação ou que piora a cada repetição é sinal para parar o exercício. Tente uma variação que não doa, com menos carga. Se continuar por mais de uma semana, inchar ou travar, procure um médico ou fisioterapeuta. Você pode marcar a articulação no perfil e a IA evita exercícios que forçam ela.'},
 {q:'Quando procurar um médico?',k:['rabdomiolise','urina escura','inchado','emergencia','medico'],r:'Dor muscular extrema, músculo muito inchado ou urina escura (cor de chá ou refrigerante de cola) depois do treino podem ser rabdomiólise: procure atendimento no mesmo dia. Dor no peito, falta de ar fora do normal ou tontura forte também. Na volta aos treinos depois de muito tempo parado, comece leve.'},
 {q:'Quanto tempo dormir?',k:['sono','dormir','dormi pouco','descansar','recuperacao'],r:'De 7 a 9 horas. É no sono que boa parte da recuperação acontece. Dormir mal derruba força, aumenta a fome e atrapalha tanto ganhar músculo quanto perder gordura.'},
 {q:'Overtraining existe?',k:['overtraining','cansado demais','sem energia','exausto','fadiga'],r:'Mais comum que overtraining é recuperação ruim: pouco sono, pouca comida e estresse. Se a força cai por 2 semanas, o sono piora e a vontade some, faça uma semana leve (deload) com metade das séries e a mesma carga.'},
 {q:'Creatina funciona?',k:['creatina'],r:'É o suplemento mais estudado para força e massa. De 3 a 5 g por dia, todo dia, em qualquer horário, sem precisar de fase de saturação. Pode reter um pouco de água dentro do músculo, o que é normal. Quem tem problema renal deve conversar com o médico antes.'},
 {q:'Preciso de whey?',k:['whey','suplemento proteina','shake','proteina em po'],r:'Whey é só comida prática: proteína do leite em pó. Ajuda a bater a meta de proteína, mas não faz nada que comida não faça. Se você já bate a meta com refeições, não precisa.'},
 {q:'Quais suplementos valem a pena?',k:['suplementos','suplemento','quais suplementos','suplementacao'],r:'Com boa evidência: creatina, cafeína antes do treino (uns 3 mg por kg, se você tolera) e whey para completar proteína. BCAA e glutamina são desnecessários para quem come proteína suficiente. Hormônios e anabolizantes têm riscos sérios à saúde e não recomendo.'},
 {q:'Quais alimentos têm mais proteína?',k:['alimentos proteina','fonte proteina','comer proteina','ricos em proteina','proteina'],r:'Ovos, frango, carne, peixe, atum em lata, leite, iogurte natural ou grego, queijo cottage, feijão, lentilha, grão de bico e tofu. Arroz com feijão e um ovo já somam uma boa quantidade. Espalhe a proteína em 3 a 5 refeições.'},
 {q:'O que comer antes do treino?',k:['antes do treino','pre treino comida','comer antes','jejum','treinar em jejum'],r:'Uma refeição normal 1 a 3 horas antes, com carboidrato e alguma proteína, ou um lanche leve 30 a 60 min antes, como banana com iogurte. Treinar em jejum é possível se você se sente bem, mas costuma render menos em treinos pesados.'},
 {q:'O que comer depois do treino?',k:['depois do treino','pos treino','janela anabolica','comer depois'],r:'Uma refeição com proteína e carboidrato nas horas seguintes. A tal janela anabólica de 30 minutos é bem mais larga do que se pensava. O total de proteína do dia importa mais que o horário.'},
 {q:'Carboidrato à noite engorda?',k:['carboidrato','carbo noite','engorda','pao','arroz'],r:'Não. O que define ganho ou perda de gordura é o total de calorias no dia, não o horário. Carboidrato é o principal combustível do treino, então corte primeiro os excessos, não ele inteiro.'},
 {q:'Como ganhar peso sendo magro?',k:['magro','ectomorfo','nao consigo engordar','ganhar peso','come muito'],r:'Quem é magro normalmente come menos do que imagina. Some calorias fáceis: leite, aveia, banana, pasta de amendoim, azeite na comida, arroz, ovos e carne moída. Coma a cada 3 ou 4 horas e pese-se uma vez por semana. Peso parado por 2 semanas pede mais umas 300 kcal.'},
 {q:'Bebida alcoólica atrapalha?',k:['alcool','cerveja','bebida','beber','vinho','chopp','destilado','drink','caipirinha','ressaca','bebida alcoolica'],r:'Atrapalha a recuperação, o sono e soma muitas calorias. Uma ocasião não estraga nada, mas beber toda semana em quantidade pesa no resultado.'},
 {q:'Cardio atrapalha ganhar massa?',k:['cardio','corrida','correr','aerobico','esteira','bike','caminhada'],r:'Em quantidade moderada, não. Duas ou três sessões de 20 a 30 min por semana ajudam o coração e a recuperação. Para não competir com as pernas, deixe o cardio intenso longe do treino de perna. Para perder gordura, caminhar todo dia é simples e funciona.'},
 {q:'Mulher que treina pesado fica masculina?',k:['mulher','feminino','masculina','ficar grande mulher','gluteo grande'],r:'Não. Mulheres têm bem menos testosterona e ganham músculo de forma mais lenta. Treinar pesado deixa o corpo mais firme e forte, e é o caminho para glúteo e pernas mais desenvolvidos.'},
 {q:'Músculo vira gordura se parar?',k:['musculo vira gordura','parar de treinar','parei','voltar a treinar','memoria muscular','destreino'],r:'Músculo não vira gordura, são tecidos diferentes. Parando, o músculo diminui aos poucos e, se a comida continuar igual, a gordura sobe. A boa notícia é a memória muscular: quem já foi forte recupera bem mais rápido do que levou para construir.'},
 {q:'Em quanto tempo vejo resultado?',k:['resultado','quanto tempo','quando vou ver','demora','primeiros resultados'],r:'Força sobe nas primeiras semanas. Mudança visível costuma aparecer entre 6 e 12 semanas de treino e dieta consistentes. Iniciante ganha de 0,5 a 1 kg de músculo por mês no melhor cenário. Tire fotos e medidas a cada 4 semanas, o espelho do dia a dia engana.'},
 {q:'Iniciante deve treinar como?',k:['iniciante','comecando','nunca treinei','primeira vez academia','comecar'],r:'Poucos exercícios básicos, técnica antes de carga, 3 ou 4 treinos por semana e progressão aos poucos. O corpo inteiro ou dividido em parte de cima e de baixo funciona muito bem. Os primeiros meses são os que mais rendem, aproveite.'},
 {q:'O que é treino ABC, full body e push pull legs?',k:['abc','abcd','full body','corpo inteiro','push pull legs','divisao','upper lower','superior inferior'],r:'São formas de dividir a semana. Full body treina tudo em cada sessão, ótimo para 2 ou 3 dias. Superior e inferior alterna parte de cima e de baixo, bom para 4 dias. Empurrar, puxar e pernas serve para 3 a 6 dias. ABC tradicional treina cada músculo uma vez por semana. A IA escolhe a divisão pelo número de dias que você tem.'},
 {q:'Como deixar o abdômen definido?',k:['abdomen','abdominal','tanquinho','barriga trincada','gomos'],r:'Os gomos aparecem com pouca gordura corporal, mais ou menos abaixo de 12% nos homens e 20% nas mulheres. Treinar o abdômen 2 ou 3 vezes por semana deixa ele mais forte e marcado, mas quem revela é a dieta.'},
 {q:'Como crescer a panturrilha?',k:['panturrilha','batata da perna','canela fina'],r:'Panturrilha responde a amplitude total e pausa: desce o calcanhar até alongar bem, segura 1 segundo e sobe até o máximo. Treine 2 ou 3 vezes por semana, com séries de 10 a 20. Genética pesa bastante nesse músculo.'},
 {q:'Como crescer o glúteo?',k:['gluteo','bumbum','bunda','gluteos'],r:'Elevação pélvica, agachamento, afundo, búlgaro e stiff são a base. Progrida a carga, treine o glúteo 2 ou 3 vezes por semana e coma proteína suficiente. Coloque glúteo como foco no seu perfil e a IA dá mais volume para ele.'},
 {q:'Como crescer o braço?',k:['braco','biceps','triceps','braco fino','crescer braco'],r:'O tríceps é dois terços do braço, então não esqueça dele. Faça roscas e extensões com amplitude completa e progressão, 8 a 14 séries por semana para cada. Supinos e remadas também trabalham o braço.'},
 {q:'Como ter ombros largos?',k:['ombro','ombros largos','deltoide','largura'],r:'A largura vem do deltoide lateral: elevação lateral com carga moderada e controle, 2 ou 3 vezes por semana. Para costas largas, puxadas e barra fixa. O deltoide da frente já trabalha muito nos supinos.'},
 {q:'Agachamento faz mal para o joelho?',k:['agachamento joelho','joelho passa ponta pe','agachar','agachamento'],r:'Feito com técnica e carga adequada, agachamento fortalece o joelho. O joelho pode passar da ponta do pé se o calcanhar continuar no chão. O cuidado é não deixar o joelho cair para dentro. Se tiver dor, use leg press ou agachamento até um banco.'},
 {q:'Como proteger a lombar?',k:['lombar','coluna','costas doem','dor nas costas'],r:'Coluna neutra nos exercícios com carga, abdômen firme e carga que você controla. Stiff e terra pedem técnica antes de peso. Prancha e extensão lombar fortalecem a região. Se já tem problema, marque lombar no perfil e a IA evita os exercícios mais exigentes.'},
 {q:'Como respirar durante o exercício?',k:['respirar','respiracao','ar'],r:'Solte o ar na fase de esforço, puxe na volta. Em exercícios pesados, segurar o ar com o abdômen firme durante a repetição protege a coluna. Só não prenda a respiração por várias repetições seguidas.'},
 {q:'Qual a velocidade da repetição?',k:['cadencia','velocidade','devagar','rapido','tempo sob tensao'],r:'Suba com firmeza e desça controlando, em uns 2 segundos. Não precisa ser lentíssimo. O importante é não deixar o peso cair e não usar impulso do corpo.'},
 {q:'Faltei ao treino, e agora?',k:['faltei','perdi treino','nao fui','pulei treino','viagem','sem tempo'],r:'Tudo bem. Faça o próximo treino da sequência e siga a vida, sem tentar compensar dobrando. Sem tempo? Um treino de 20 minutos só com os exercícios principais já mantém o progresso.'},
 {q:'Como treinar em casa?',k:['treinar em casa','casa','sem academia','sem equipamento','peso do corpo','halteres em casa'],r:'Dá para evoluir bem em casa com flexões, agachamentos, afundos, búlgaro, remada com mochila e ponte de glúteo. Para progredir, aumente repetições, desça mais devagar ou use mochila com peso. Um par de halteres ajustáveis amplia muito as opções. Mude o local no perfil e a IA refaz o plano.'},
 {q:'Como medir meu progresso?',k:['medir progresso','medidas','fotos','balanca','evolucao','acompanhar'],r:'Peso uma vez por semana, no mesmo dia, em jejum. Medidas de cintura, braço e coxa a cada 2 a 4 semanas. Fotos na mesma luz e posição. E as cargas no app, que mostram se você está ficando mais forte.'},
 {q:'Treino de força ou hipertrofia, qual a diferença?',k:['forca','powerlifting','ficar forte','1rm','carga maxima'],r:'Força usa menos repetições (3 a 6), mais carga e descansos longos, com foco nos básicos. Hipertrofia usa mais repetições e mais séries. Na prática as duas se ajudam: ficar mais forte em 10 repetições também faz crescer.'},
 {q:'Idade atrapalha ganhar músculo?',k:['idade','velho','40 anos','50 anos','60 anos','idoso','terceira idade'],r:'Ganha-se músculo em qualquer idade. Depois dos 40 a recuperação fica um pouco mais lenta, então vale cuidar do aquecimento, do sono e de comer proteína suficiente. Musculação é um dos melhores remédios para envelhecer bem.'},
 {q:'Como usar o app?',k:['como usar o app','usar o app','tutorial','funcoes do app','como funciona o app'],r:'Em Treino você vê o treino do dia e toca em Começar. Faça a série em laranja e toque em Concluir série: começa o descanso e a próxima série acende. Dá para voltar e avançar entre exercícios e tocar em qualquer série para refazer. Em Plano você personaliza dias e exercícios. Em Evolução ficam gráficos, corpo e histórico.'},
 /* ---- treino: intensidade, planejamento e técnica ---- */
 {q:'O que é RIR e RPE?',k:['rir','rpe','repeticoes na reserva','perto da falha','intensidade','esforco da serie'],frase:['repeticoes na reserva','quao perto da falha'],r:'RIR é quantas repetições ainda sobrariam no fim da série. RIR 2 quer dizer que você pararia com mais duas no tanque. Para crescer, deixe a maioria das séries entre 0 e 3 repetições da falha. RPE é a mesma ideia numa escala de 1 a 10: RPE 8 equivale a RIR 2.'},
 {q:'O que é deload?',frase:['o que e deload','semana de deload'],k:['deload','semana leve','descarga','periodizacao','periodizar','mesociclo'],r:'Deload é uma semana mais leve, com metade das séries ou cargas menores, para o corpo se recuperar. Não precisa ser fixo: faça quando as cargas pararem de subir por duas semanas, as articulações reclamarem ou o cansaço acumular. Periodizar é organizar o treino em blocos, mudando volume e intensidade ao longo das semanas.'},
 {q:'Estagnei, o que fazer?',k:['estagnei','estagnado','plato','parei de evoluir','nao evoluo','nao cresco','travei','carga nao sobe','nao progrido'],frase:['parei de evoluir','nao estou evoluindo','nao consigo evoluir'],r:'Confira nesta ordem: sono de pelo menos 7 horas, proteína batendo a meta, calorias suficientes e séries de verdade perto da falha. Se tudo isso estiver em dia, faça uma semana leve e depois varie: troque um exercício por outro do mesmo músculo ou mude a faixa de repetições, de 6 a 8 para 10 a 15.'},
 {q:'Quanto tempo deve durar o treino?',k:['duracao do treino','treino longo','treino curto','treino de 20 minutos','treino de 30 minutos','pouco tempo','hora de treino'],frase:['quanto tempo deve durar','treino de 20 minutos','treino curto funciona'],r:'Entre 40 e 75 minutos atende quase todo mundo. Treino curto funciona: 20 a 30 minutos com séries perto da falha e descansos mais curtos já dão resultado, ainda mais com 3 ou mais treinos por semana. O que mais pesa é a constância ao longo dos meses.'},
 {q:'Posso treinar todo dia?',k:['todo dia','todos os dias','treinar todo dia','dias seguidos','mesmo musculo','dia de descanso'],frase:['treinar todo dia','dias seguidos','mesmo musculo dois dias'],r:'Pode, desde que não repita o mesmo músculo pesado em dias seguidos. O músculo precisa de 48 a 72 horas para se recuperar de um treino forte. Dividir os grupos ao longo da semana, como o app faz, resolve isso. Um ou dois dias de descanso por semana ajudam a manter a vontade e a recuperação em dia.'},
 {q:'Amplitude completa ou parcial?',k:['amplitude','amplitude completa','parcial','parciais','meia repeticao','descer ate embaixo','rom'],r:'Use a maior amplitude que você controla sem dor. Estudos mostram que treinar com o músculo bem alongado, como descer bem no agachamento ou abrir bem no supino com halteres, faz crescer mais. Repetições parciais na parte alongada podem entrar no fim da série como extra.'},
 {q:'Conexão mente-músculo funciona?',k:['mente musculo','conexao mente','sentir o musculo','nao sinto','concentrar no musculo','nao sinto o peito','nao sinto as costas'],frase:['nao sinto','sentir o musculo'],r:'Funciona em exercícios isolados e com cargas moderadas: pensar no músculo trabalhando aumenta a ativação dele. Se não sente o músculo, diminua a carga, desça mais devagar, em uns 2 a 3 segundos, e pause na parte mais difícil. Em exercícios pesados, o foco deve ser a execução.'},
 {q:'Máquina ou peso livre?',k:['maquina ou peso livre','peso livre','maquinas','maquina e pior','smith'],frase:['maquina ou peso livre','maquina ou livre','maquina e pior'],r:'Os dois fazem crescer igual quando o esforço é o mesmo. Máquinas são mais seguras, fáceis de aprender e ótimas para chegar perto da falha. Peso livre trabalha mais o equilíbrio e a coordenação. Use os dois, do jeito que você treina melhor.'},
 {q:'Halteres ou barra?',k:['halter ou barra','barra ou halter','halteres ou barra','unilateral','um lado de cada vez'],frase:['halter ou barra','barra ou halter','halteres ou barra'],r:'A barra permite mais carga e facilita medir a progressão. Os halteres dão mais amplitude, deixam cada lado trabalhar sozinho e costumam ser mais confortáveis para ombros e punhos. Exercícios unilaterais ajudam a corrigir diferenças entre os lados.'},
 {q:'Um lado mais forte que o outro, e agora?',k:['um lado mais forte','assimetria','assimetrico','lado mais fraco','braco maior','simetria','desequilibrio'],frase:['um lado mais','lado mais fraco','um braco maior'],r:'É normal ter uma diferença pequena. Use halteres e exercícios unilaterais, comece pelo lado mais fraco e faça no lado forte o mesmo número de repetições que o fraco conseguiu. Em alguns meses a diferença diminui. Se for grande ou vier com dor, vale uma avaliação de fisioterapeuta.'},
 {q:'Cardio antes ou depois da musculação?',k:['cardio antes','cardio depois','aerobico antes','esteira antes','ordem do cardio'],frase:['cardio antes','antes ou depois da musculacao','aerobico antes','esteira antes'],r:'Se o objetivo é força ou massa, faça a musculação primeiro e o cardio depois, ou em outro horário. Cardio leve de 5 a 10 minutos antes serve como aquecimento. Se o foco for corrida ou condicionamento, inverta.'},
 {q:'HIIT ou cardio contínuo?',k:['hiit','intervalado','cardio continuo','aerobico moderado','qual cardio','melhor cardio','aerobico'],frase:['hiit ou','melhor cardio','qual o melhor aerobico','cardio para emagrecer'],r:'Os dois queimam gordura de forma parecida quando o gasto total é o mesmo. HIIT economiza tempo, mas cansa mais e atrapalha a recuperação das pernas se for frequente. Cardio moderado, como caminhada rápida ou bicicleta, é fácil de manter e interfere menos na musculação. Para a maioria, 2 a 3 sessões moderadas e no máximo 1 a 2 de HIIT por semana.'},
 {q:'Quantos passos por dia?',k:['passos','passos por dia','neat','10 mil passos','andar mais'],frase:['passos por dia','10 mil passos','quantos passos'],r:'Entre 7 e 10 mil passos por dia já trazem grande parte dos benefícios para a saúde. Para emagrecer, aumentar os passos é um dos jeitos mais fáceis de gastar mais sem atrapalhar o treino. Some aos poucos, uns 1.000 a 2.000 por semana.'},
 {q:'Como começar a correr?',k:['comecar a correr','corredor','5 km','pace','corrida e musculacao'],frase:['comecar a correr','correr e musculacao','correr e treinar'],r:'Comece alternando 1 minuto correndo e 2 andando, por 20 a 30 minutos, 3 vezes por semana. A cada semana aumente um pouco o tempo correndo. Corra num ritmo em que dá para conversar. Corrida e musculação combinam bem: deixe a corrida forte longe do treino de perna.'},
 {q:'Como ganhar mobilidade?',k:['mobilidade','flexibilidade','travado','encurtado','tornozelo','quadril travado','alcancar o pe'],frase:['ganhar mobilidade','sou travado','muito encurtado','ganhar flexibilidade'],r:'A própria musculação com amplitude completa melhora a mobilidade. Some 5 a 10 minutos de mobilidade antes do treino nas regiões travadas, como quadril, tornozelo e a parte de cima das costas, e alongamentos de 30 a 60 segundos depois ou em outro horário, de 3 a 5 vezes por semana.'},
 {q:'Como melhorar a postura?',k:['postura','ombro para frente','corcunda','cifose','ombros caidos','coluna torta','escoliose','curvado'],frase:['melhorar a postura','ombro para frente','ombros para frente'],r:'Fortaleça as costas e a parte de trás dos ombros com remadas, face pull e crucifixo inverso, e não abandone o core. Mude de posição com frequência ao longo do dia: nenhuma postura é ruim, ficar muito tempo parado nela é que cansa. Dor persistente ou desvio grande merecem avaliação.'},
 /* ---- treino por músculo ---- */
 {q:'Como ter costas largas?',k:['costas largas','costas grandes','v shape','formato em v','largura','dorsal'],frase:['costas largas','formato de v','formato em v'],r:'Largura vem principalmente do latíssimo: barra fixa, puxada e pulldown. Espessura vem das remadas. Faça 10 a 20 séries de costas por semana, divididas entre puxadas verticais e remadas, e trabalhe a elevação lateral para alargar os ombros, o que reforça o formato em V.'},
 {q:'Como crescer o peito?',k:['crescer o peito','peitoral','peito grande','peito nao cresce','aumentar o peito'],frase:['crescer o peito','aumentar o peito','peito nao cresce','sinto mais o ombro'],r:'Supino com barra ou halteres e uma variação inclinada são a base. Some crucifixo ou cross-over para trabalhar o peito alongado. De 10 a 20 séries por semana, com progressão de carga. Se sente mais o ombro que o peito, junte as escápulas, desça a barra na linha do peito e não abra demais os cotovelos.'},
 {q:'Como crescer as pernas?',k:['crescer a perna','pernas grandes','coxa','quadriceps','perna fina','perna nao cresce'],frase:['crescer a perna','crescer as pernas','perna fina','engrossar a perna'],r:'Agachamento, leg press ou búlgaro como base, cadeira extensora para o quadríceps e mesa ou cadeira flexora e stiff para o posterior. Desça bem nos exercícios e faça as séries perto da falha. Perna responde a volume: 10 a 20 séries por semana para o quadríceps e uns 10 para o posterior.'},
 {q:'Como fortalecer o posterior de coxa?',k:['posterior de coxa','isquiotibiais','flexora','terra romeno','posterior fraco'],frase:['posterior de coxa'],r:'Combine um exercício que dobra o quadril, como stiff ou terra romeno, com um que dobra o joelho, como mesa ou cadeira flexora. A cadeira flexora sentada trabalha o músculo mais alongado e costuma render mais. Posterior forte também protege o joelho e a lombar.'},
 {q:'Como ter mais pegada?',k:['pegada','grip','mao escorrega','segurar a barra','strap','straps','fita'],frase:['melhorar a pegada','mais pegada','pegada fraca'],r:'Segure firme em todas as puxadas e remadas e faça a caminhada do fazendeiro ou fique pendurado na barra no fim do treino. Para séries pesadas de costas, straps ajudam a pegada não limitar o músculo, mas use só nas séries mais pesadas.'},
 {q:'Como crescer o trapézio?',k:['trapezio','pescoco grosso','encolhimento','ombro alto','trapezio maior'],frase:['crescer o trapezio','trapezio maior'],r:'Encolhimento com halteres ou barra, segurando 1 segundo no alto, é o principal. Remadas, terra e elevação lateral também trabalham o trapézio. Umas 6 a 10 séries diretas por semana bastam para a maioria.'},
 {q:'Posso fazer abdominal todo dia?',k:['abdominal todo dia','abdomen todo dia','abdominal diario','quantos abdominais','centenas de abdominais'],frase:['abdominal todo dia','abdominais por dia'],r:'Pode, mas não precisa. O abdômen responde como qualquer músculo: 2 a 3 treinos por semana, com carga e séries perto da falha, rendem mais que centenas de repetições leves todo dia. E o tanquinho só aparece com a gordura baixa.'},
 /* ---- equipamentos e modalidades ---- */
 {q:'Preciso de cinto, luva ou munhequeira?',k:['cinto','luva','luvas','munhequeira','joelheira','acessorio','calo','calos'],frase:['preciso de cinto','usar luva','usar cinto'],r:'Não são obrigatórios. Cinto ajuda em séries muito pesadas de agachamento e terra, para quem já tem boa técnica. Munhequeira dá apoio ao punho no supino pesado. Luva evita calo, mas pode piorar a pegada. Para iniciante, nada disso é necessário.'},
 {q:'Qual tênis usar na academia?',k:['tenis para treinar','calcado','descalco','sapato','sola','tenis de corrida'],frase:['qual tenis','tenis para academia','treinar descalco'],r:'Para musculação, prefira tênis de sola baixa e firme, que dá estabilidade no agachamento e no terra. Tênis de corrida com muito amortecimento deixam o pé instável nos exercícios pesados. Na esteira ou na rua, use um tênis de corrida.'},
 {q:'Calistenia funciona?',k:['calistenia','street workout','barras e paralelas','treino sem peso'],r:'Funciona muito bem para ganhar força e músculo, desde que você vá dificultando: mais repetições, descida lenta, variações mais difíceis ou colete com peso. O limite é que pernas e alguns músculos menores ficam difíceis de progredir só com o peso do corpo.'},
 {q:'Crossfit ou funcional é melhor que musculação?',k:['crossfit','funcional','treino funcional','cross training'],r:'Cada um tem seu foco. Crossfit e funcional melhoram o condicionamento e trabalham o corpo todo, mas progridem menos a força de cada músculo. Para ganhar massa e forma, a musculação é mais direta. Combinar dá certo se a recuperação aguentar.'},
 {q:'Pilates ou yoga ajudam?',k:['pilates','yoga','ioga'],r:'Ajudam na mobilidade, no controle do corpo e no relaxamento, e o pilates fortalece o core. Mas não substituem a musculação para ganhar força e massa. Funcionam bem como complemento, 1 ou 2 vezes por semana.'},
 /* ---- grupos e fases da vida ---- */
 {q:'O ciclo menstrual muda o treino?',k:['menstruacao','ciclo menstrual','menstruada','tpm','colica','anticoncepcional'],frase:['ciclo menstrual','treinar menstruada'],r:'Pode treinar em qualquer fase. Alguns dias de cólica ou cansaço pedem um treino mais leve, e tudo bem. Na semana antes da menstruação é comum o peso subir de 1 a 2 kg por retenção de líquido, que some depois. Compare o peso sempre na mesma fase do ciclo.'},
 {q:'Posso treinar grávida?',k:['gravida','gravidez','gestante','gestacao','pos parto','amamentando'],frase:['treinar gravida','treinar na gravidez'],r:'Na maioria das gestações saudáveis, exercício moderado é recomendado, uns 150 minutos por semana. Converse antes com o obstetra. Evite ficar deitada de barriga para cima por muito tempo depois do primeiro trimestre, exercícios com risco de queda ou impacto na barriga e prender a respiração com carga muito pesada.'},
 {q:'Adolescente pode fazer musculação?',k:['adolescente','crianca','menor de idade','14 anos','15 anos','16 anos','atrapalha crescer','para de crescer'],frase:['atrapalha o crescimento','para de crescer','atrapalha crescer'],r:'Pode, com orientação e boa técnica. Musculação não atrapalha o crescimento: o que machuca são acidentes por carga exagerada e execução ruim. Comece leve, aprenda os movimentos e suba a carga aos poucos.'},
 /* ---- lesões e sintomas ---- */
 {q:'O que fazer com cãibra?',k:['caibra','caimbra','espasmo','musculo travou','fisgada'],frase:['deu caibra','tive caibra'],r:'Pare e alongue o músculo devagar até passar. Cãibra no treino costuma vir do cansaço do músculo, e não só de falta de sal ou potássio. Beba água, coma direito e aumente o volume do treino aos poucos. Se for frequente fora do treino, procure um médico.'},
 {q:'Fiquei tonto no treino, e agora?',k:['tontura','tonto','enjoo','enjoado','vista escura','pressao baixa','passei mal','desmaiar','vomitar'],frase:['fiquei tonto','passei mal no treino','vista escureceu'],r:'Pare, sente ou deite com as pernas para cima e beba água. Costuma ser falta de comida, pouca água, levantar rápido demais ou prender a respiração. Coma algo 1 a 2 horas antes de treinar. Se vier com dor no peito, falta de ar forte ou se repetir, procure um médico.'},
 {q:'Tenho tendinite, posso treinar?',k:['tendinite','tendao','epicondilite','cotovelo de tenista','bursite','inflamacao'],r:'Na maioria das vezes, sim, com ajustes. Tendão melhora com carga bem dosada: evite o movimento que dói, use cargas moderadas e descidas lentas e aceite um incômodo leve, até 3 numa escala de 10, que passa até o dia seguinte. Se piorar, procure um fisioterapeuta. Dá para marcar a lesão no perfil.'},
 {q:'O que é canelite?',k:['canelite','dor na canela','canela'],r:'É uma dor na frente ou na parte de dentro da canela, comum em quem aumentou a corrida ou os saltos rápido demais. Diminua o impacto por um tempo, troque por bicicleta ou elíptico e volte aos poucos. Fortalecer a panturrilha ajuda a prevenir. Dor muito pontual pode ser fratura por estresse e merece avaliação.'},
 {q:'Quem tem hérnia de disco pode treinar?',k:['hernia','hernia de disco','protusao','ciatico','ciatica','bico de papagaio'],frase:['hernia de disco','tem hernia','tenho hernia'],r:'Pode e geralmente deve, com orientação. Fortalecer o core, os glúteos e as costas costuma reduzir as crises. Evite o que dá dor irradiando para a perna, comece com cargas leves e coluna neutra. Com dormência, perda de força ou dor forte, procure um médico antes. Marque lombar no perfil para a IA evitar os exercícios de mais risco.'},
 {q:'Joelho estalando é problema?',k:['estalo','estala','estalando','crepitacao','barulho no joelho','joelho estala'],frase:['joelho estala','joelho estalando','ombro estala'],r:'Estalo sem dor é muito comum e normalmente não significa nada. O que merece atenção é estalo com dor, inchaço ou sensação de travar ou falsear. Nesses casos, alivie o exercício e procure avaliação.'},
 {q:'Voltei a treinar depois de parado, como recomeçar?',k:['voltar a treinar','voltando a treinar','fiquei parado','memoria muscular','retornar','recomecar','parei de treinar'],frase:['voltar a treinar','fiquei parado','memoria muscular','fiquei sem treinar'],r:'Comece com metade a dois terços das cargas que usava e menos séries na primeira semana, para evitar dor exagerada. A memória muscular é real: quem já teve músculo recupera bem mais rápido do que levou para ganhar da primeira vez. Em 4 a 8 semanas a maioria volta ao nível antigo.'},
 {q:'Posso treinar gripado?',k:['gripado','gripada','gripe','resfriado','doente','febre','covid','dor de garganta'],frase:['treinar gripado','treinar doente','treinar gripada','estou gripado','estou resfriado','estou gripada','estou resfriada'],r:'Com sintomas só do pescoço para cima, como nariz entupido, um treino leve costuma ir bem. Com febre, dor no corpo, falta de ar ou sintomas no peito, descanse até melhorar. Na volta, comece mais leve por 1 ou 2 treinos.'},
 {q:'Estresse atrapalha os resultados?',k:['estresse','stress','cortisol','ansiedade','cansaco mental','trabalho puxado'],frase:['ansiedade atrapalha','estresse atrapalha','stress atrapalha'],r:'Estresse alto e por muito tempo piora o sono, a fome e a recuperação, então atrapalha. O treino em si ajuda a reduzir o estresse e a ansiedade. Nas fases mais puxadas, mantenha o treino mais curto e foque em dormir bem.'},
 {q:'Como aumentar a testosterona naturalmente?',k:['testosterona','hormonio','hormonios','aumentar testosterona','libido','testosterona baixa'],frase:['testosterona baixa'],r:'Os básicos funcionam melhor que qualquer cápsula: dormir 7 a 9 horas, manter a gordura corporal em nível saudável, comer gordura suficiente, treinar pesado e controlar o álcool. Suplementos que prometem aumentar a testosterona quase sempre não fazem diferença. Sintomas de testosterona baixa pedem exame com um médico.'},
 {q:'Anabolizantes valem a pena?',k:['anabolizante','anabolizantes','bomba','esteroide','esteroides','trembolona','oxandrolona','ciclo de bomba'],r:'Não recomendo. Trazem riscos sérios para o coração, o fígado, a fertilidade e o humor, e muitos efeitos não voltam ao parar. Quem é natural ganha muito músculo nos primeiros anos com treino, comida e sono. Se pensar em usar algo, faça só com acompanhamento médico.'},
 {q:'Genética ou biotipo limitam o resultado?',k:['genetica','biotipo','ectomorfo','endomorfo','mesomorfo','metabolismo rapido','magro de ruim'],frase:['genetica ruim','sou ectomorfo','meu biotipo'],r:'A genética muda o ritmo e o formato final, mas todo mundo melhora muito com treino e comida certos. Biotipos como ectomorfo são uma simplificação: quem tem dificuldade de ganhar peso precisa, na prática, comer mais do que acha. Compare você com você mesmo.'},
 /* ---- corpo e estética ---- */
 {q:'Como acabar com a celulite e a flacidez?',k:['celulite','flacidez','flacido','flacida','pele solta','pele flacida'],r:'Celulite é normal e aparece em quase todas as mulheres, até nas magras. Ganhar músculo e diminuir a gordura deixa a pele mais firme e a celulite menos visível, mas raramente ela some por completo. Cremes ajudam pouco. Flacidez melhora muito com musculação e perda de gordura sem pressa.'},
 {q:'Estrias somem?',k:['estria','estrias'],r:'Estrias vêm do crescimento rápido da pele e da genética. Com o tempo elas clareiam e ficam menos visíveis, mas raramente somem por completo. Ganhar e perder peso devagar reduz o surgimento de novas. Tratamentos com dermatologista podem melhorar a aparência.'},
 {q:'Meu metabolismo está lento?',k:['metabolismo lento','adaptacao metabolica','nao emagreco','parei de emagrecer','plato na dieta','balanca parada','balanca nao mexe'],frase:['parei de emagrecer','nao consigo emagrecer','balanca nao mexe','metabolismo lento'],r:'O metabolismo cai um pouco na dieta, mas não trava o emagrecimento. Quando a balança para por 2 a 3 semanas, geralmente é retenção de líquido ou as calorias subiram sem você perceber. Pese a comida por uns dias, aumente os passos e, se precisar, corte mais 100 a 200 kcal. Depois de meses em déficit, uma pausa de 1 a 2 semanas na manutenção ajuda.'},
 {q:'Por que meu peso subiu de um dia para o outro?',k:['peso subiu','engordei de um dia','retencao','inchado','inchada','retendo liquido','peso oscila','agua no corpo'],frase:['peso subiu','engordei 1 kg','retencao de liquido','de um dia para o outro'],r:'Variação de 0,5 a 2 kg em um dia é água e comida no intestino, não gordura. Refeição com mais sal ou carboidrato, treino pesado, pouco sono e o ciclo menstrual fazem o peso oscilar. Olhe a média da semana: ela mostra a tendência real. Para ganhar 1 kg de gordura seriam umas 7.000 kcal a mais.'},
 {q:'Comecei a treinar e o peso subiu, é normal?',k:['comecei a treinar e engordei','peso subiu treinando','ganhei peso treinando','engordei treinando'],frase:['comecei a treinar e','engordei treinando','engordei depois que comecei'],r:'É normal no começo. O músculo treinado guarda mais glicogênio e água, e isso aparece na balança em 1 a 2 semanas. Por isso vale acompanhar também a cintura, as fotos e as cargas, e não só o peso.'},
 {q:'Qual a cintura ideal?',k:['cintura ideal','medida da cintura','circunferencia','relacao cintura altura','barriga grande'],frase:['cintura ideal'],r:'Uma referência simples: a cintura deve ter menos da metade da sua altura. Para 1,70 m, menos de 85 cm. Cintura acima disso indica mais gordura na barriga, que é a mais ligada a riscos para a saúde. Meça na altura do umbigo, sem apertar e sem prender a respiração.'},
 {q:'Como medir o percentual de gordura?',k:['medir percentual','bioimpedancia','adipometro','dobras cutaneas','dexa','balanca de bioimpedancia'],frase:['bioimpedancia','como medir o percentual'],r:'DEXA é o mais preciso. Dobras cutâneas com um bom avaliador funcionam bem. Bioimpedância varia muito com a água do corpo, então use sempre nas mesmas condições e olhe a tendência. Se você registrar a cintura em Evolução, eu estimo o seu percentual pela relação entre cintura e altura.'},
 {q:'Quanto treino para manter o resultado?',k:['manter','manutencao','manter massa','ferias','viagem','viajando'],frase:['manter os resultados','manter a massa','treinar na viagem','vou viajar'],r:'Manter é bem mais fácil que ganhar. Com 1 a 2 treinos por semana, mantendo as cargas e umas 4 a 6 séries por músculo, dá para segurar a massa e a força por meses. Em viagem, flexões, agachamentos e afundos num treino curto já ajudam.'},
 {q:'Quanto músculo dá para ganhar por mês?',k:['quanto musculo','quilos de musculo','ganho por mes','ganhar por mes'],frase:['quanto musculo','ganhar por mes','quantos quilos de musculo'],r:'Iniciantes bem orientados ganham de 0,5 a 1 kg de músculo por mês no primeiro ano. Depois o ritmo cai para uns 0,25 a 0,5 kg por mês, e fica ainda menor com os anos. Mulheres costumam ganhar cerca da metade disso. Ganhar peso muito mais rápido que isso vira gordura.'},
 {q:'Como ter constância e motivação?',k:['motivacao','preguica','desanimo','desanimado','constancia','disciplina','desisto','sem vontade','nao consigo ir'],frase:['sem motivacao','nao tenho motivacao','como ter constancia','estou com preguica'],r:'Não dependa da motivação, crie rotina: horário fixo, roupa separada e treino curto nos dias ruins. Um treino de 20 minutos é muito melhor que nenhum. Veja as cargas subindo em Evolução: perceber o progresso é o que mais motiva. Se faltar, volte no próximo dia sem tentar compensar.'},
 /* ---- nutrição ---- */
 {q:'Como contar calorias?',k:['contar calorias','contar macro','contar macros','pesar comida','balanca de cozinha','sem balanca','medida caseira','porcao com a mao'],frase:['contar calorias','pesar a comida','sem balanca'],r:'Pese o que come por 1 a 2 semanas para aprender as porções, depois dá para estimar. Sem balança, use a mão: uma palma de proteína, um punho de carboidrato, duas mãos de legumes e um polegar de gordura por refeição. Aqui no chat você pode perguntar quantas calorias tem cada alimento.'},
 {q:'Refeição livre atrapalha?',k:['refeicao livre','dia do lixo','jacar','jacada','chutar o balde','chutei o balde','lixo no fim de semana'],frase:['refeicao livre','dia do lixo','chutei o balde','fim de semana'],r:'Uma refeição livre por semana cabe bem, sem culpa. O problema é o dia inteiro do lixo, que pode apagar o déficit da semana toda. Se exagerou, não compense passando fome: volte ao normal na próxima refeição.'},
 {q:'Para que servem as fibras?',k:['fibra','fibras','intestino preso','constipacao','prisao de ventre'],r:'Fibras dão saciedade, ajudam o intestino e controlam a glicose. A meta é uns 25 a 35 g por dia: frutas com casca, verduras, legumes, feijão, aveia e integrais. Aumente aos poucos e beba água junto, senão o intestino pode prender mais.'},
 {q:'Sal faz mal?',k:['sal','sodio','pressao alta','hipertensao','tempero pronto'],frase:['sal faz mal','muito sal'],r:'O sódio é necessário, ainda mais para quem sua muito no treino, mas o brasileiro come em média o dobro do recomendado, que é até 5 g de sal por dia. O excesso vem mais de ultraprocessados, embutidos e temperos prontos do que do saleiro. Quem tem pressão alta precisa de mais cuidado.'},
 {q:'Adoçante faz mal?',k:['adocante','sucralose','stevia','aspartame','xilitol','zero acucar'],r:'Nas quantidades normais, os adoçantes aprovados são seguros. Trocar açúcar por adoçante ajuda a cortar calorias, principalmente nas bebidas. Refrigerante zero é melhor que o comum para quem quer emagrecer, mas água continua sendo a melhor opção.'},
 {q:'Ultraprocessados atrapalham?',k:['ultraprocessado','ultraprocessados','industrializado','industrializados','salgadinho','embutido','embutidos','comida pronta'],r:'Eles têm muitas calorias, pouca saciedade e são fáceis de comer em excesso. Num estudo, as pessoas comeram umas 500 kcal a mais por dia com uma dieta de ultraprocessados. Não precisa zerar, mas a base do dia deve ser comida de verdade.'},
 {q:'Café antes do treino ajuda?',k:['cafe antes do treino','cafeina','energetico','energia para treinar'],frase:['cafe antes do treino','cafeina antes','tomar cafe antes','cafeina melhora'],r:'Ajuda. A cafeína melhora a força, a resistência e a disposição, com 3 a 6 mg por kg de 30 a 60 minutos antes. Uma xícara de café coado tem uns 80 a 100 mg. Evite depois das 16h, porque atrapalha o sono, e comece com doses baixas.'},
 {q:'Pré-treino e termogênico funcionam?',k:['pre treino em po','suplemento pre treino','termogenico','termogenicos','queimador','queimador de gordura','beta alanina'],frase:['pre treino funciona','termogenico funciona','vale tomar pre treino'],r:'O efeito do pré-treino vem quase todo da cafeína: um café faz parecido e custa menos. Beta-alanina ajuda um pouco em séries longas e dá formigamento, que é inofensivo. Termogênicos queimam pouquíssimas calorias a mais e podem dar taquicardia e insônia. O que emagrece é o déficit.'},
 {q:'BCAA e glutamina valem a pena?',k:['bcaa','glutamina','aminoacido','aminoacidos','leucina'],r:'Para quem já come proteína suficiente, não fazem diferença. BCAA são só 3 dos aminoácidos que já vêm na comida e no whey. Glutamina não melhora a força nem a massa em pessoas saudáveis. O dinheiro rende mais em comida, whey ou creatina.'},
 {q:'Ômega 3, vitamina D e multivitamínico ajudam?',k:['omega 3','omega','vitamina d','multivitaminico','vitamina','vitaminas','magnesio','zinco','zma'],r:'Só fazem diferença se faltar. Vitamina D baixa é comum em quem pega pouco sol e vale conferir no exame de sangue. Ômega 3 serve para quem come pouco peixe. Multivitamínico não melhora o treino de quem come variado. Converse com seu médico antes de tomar doses altas.'},
 {q:'Colágeno ajuda?',k:['colageno','colageno hidrolisado'],r:'Colágeno é uma proteína incompleta e não substitui carne, ovo ou whey para o músculo. Alguns estudos mostram pequena melhora em dor articular e na pele, com 10 a 15 g por dia junto com vitamina C. É opcional, não essencial.'},
 {q:'Proteína demais faz mal aos rins?',k:['rim','rins','proteina faz mal','muita proteina','excesso de proteina','proteina demais'],frase:['proteina faz mal','proteina demais','faz mal pro rim','faz mal para o rim'],r:'Para quem tem rins saudáveis, até uns 2,2 g por kg por dia é seguro, e os estudos não mostram dano mesmo um pouco acima disso. Quem já tem doença renal precisa de orientação médica e controle da proteína. Beba água suficiente ao longo do dia.'},
 {q:'Ovo aumenta o colesterol?',k:['colesterol','ovo faz mal','gema','ovos por dia'],frase:['quantos ovos por dia','ovo faz mal','ovo aumenta o colesterol'],r:'Para a maioria das pessoas, o colesterol do ovo influencia pouco o do sangue. Até 2 a 3 ovos por dia entram bem numa dieta equilibrada. Quem já tem colesterol alto ou diabetes deve ver com o médico. A gema tem boa parte das vitaminas, não precisa jogar fora.'},
 {q:'Tirar glúten ou lactose emagrece?',k:['gluten','sem gluten','tirar o gluten','celiaco'],frase:['gluten engorda','sem gluten'],r:'Não. Só ajuda quem tem doença celíaca, sensibilidade ou intolerância. Quem emagrece tirando o glúten geralmente emagrece porque cortou pão, bolo e massas, ou seja, calorias. Se não tem problema com eles, não precisa cortar.'},
 {q:'Low carb ou dieta cetogênica emagrecem mais?',k:['low carb','lowcarb','cetogenica','keto','cortar carboidrato','sem carboidrato'],frase:['low carb','dieta cetogenica','cortar carboidrato'],r:'Com as mesmas calorias e proteína, emagrecem parecido com uma dieta comum. No começo a balança cai mais rápido por perda de água. Para quem treina pesado, cortar muito carboidrato costuma piorar o rendimento. Funciona para quem se adapta, mas não é obrigatório.'},
 {q:'Dieta muito restrita funciona?',k:['1200 calorias','dieta restritiva','comer pouco','passar fome','dieta da sopa','fechar a boca','dieta radical'],frase:['passar fome','dieta radical','comer muito pouco','1200 calorias','dieta de 1200'],r:'Funciona por pouco tempo e costuma terminar em efeito sanfona. Déficit grande faz perder mais músculo, dá fome, cansaço e piora o treino. Um déficit moderado, de 300 a 500 kcal, com proteína alta, é mais fácil de manter e preserva o músculo.'},
 {q:'Fruta engorda?',k:['fruta engorda','frutas','suco engorda','frutose','acucar da fruta'],frase:['fruta engorda','suco engorda','frutas engordam'],r:'Fruta inteira dificilmente engorda: tem fibras, água e mata a fome. Duas a quatro porções por dia são ótimas. O suco concentra o açúcar e mata menos a fome, então prefira comer a fruta. A frutose da fruta não é o problema, e sim o total de calorias.'},
 {q:'Chá ou detox emagrecem?',k:['detox','cha emagrece','cha verde','agua com limao','limao em jejum','vinagre de maca','suco verde','cha de hibisco'],frase:['cha emagrece','suco detox','agua com limao','vinagre de maca'],r:'Não de forma relevante. Chás e sucos detox têm pouquíssima caloria e podem ajudar a beber mais água, mas não derretem gordura nem limpam o corpo, que já faz isso pelo fígado e pelos rins. A perda rápida que alguns prometem é só água.'},
 {q:'Posso comer antes de dormir?',k:['antes de dormir','ceia','fome a noite','comer tarde da noite'],frase:['antes de dormir','comer de madrugada'],r:'Pode. O que importa é o total do dia. Uma refeição com proteína antes de dormir, como iogurte, leite, ovos ou queijo cottage, ajuda a bater a meta e a recuperação. Evite refeições muito pesadas se elas atrapalham o seu sono.'},
 {q:'Melhor horário para treinar?',k:['melhor horario','horario de treino','treinar de manha','treinar a noite','treinar cedo','que horas treinar'],frase:['melhor horario','treinar de manha ou','treinar a noite'],r:'O melhor horário é o que você consegue manter. A força costuma ser um pouco maior no fim da tarde, mas a diferença some quando você treina sempre no mesmo horário. Se treinar à noite atrapalhar o sono, adiante o treino ou corte o café.'},
 {q:'Suar mais emagrece?',k:['suar','suor','sauna','cinta','agasalho','cinta modeladora','suar mais'],frase:['suar emagrece','suar mais','cinta na academia','usar cinta'],r:'Não. Suor é água, que volta quando você bebe. Sauna, agasalho no calor ou cinta dão uma perda de peso falsa e aumentam o risco de desidratação. O que tira gordura é gastar mais energia do que come ao longo das semanas.'},
 {q:'Como se hidratar no treino?',k:['hidratar no treino','isotonico','gatorade','beber agua no treino','desidratacao','agua durante o treino'],frase:['beber agua no treino','isotonico','agua durante o treino','durante o treino'],r:'Beba água ao longo do dia e uns goles a cada 15 a 20 minutos de treino. Isotônico só faz diferença em treinos acima de 1 hora, com muito suor ou no calor. Urina clara é o melhor sinal de que você está bem hidratado.'}
];
